			var oShapeid = window.external.parentWindow.document.activeElement.id.substring(0, window.external.parentWindow.document.activeElement.id.indexOf("_"));
			var oShape = window.external.parentWindow.document.getElementById(oShapeid);
			if (oShape.value ==2)oShape.Objects("RGConalpTagName").focus;
			if (oShape.value ==3)oShape.Objects("RVConalpTagName").focus;
			if (oShape.value ==4)oShape.Objects("DIConalpTagName").focus;
			window.external.application.InvokeCommand('Request Point Detail');

			window.external.CloseShortcutMenu();

			var oShapeid = window.external.parentWindow.document.activeElement.id.substring(0, window.external.parentWindow.document.activeElement.id.indexOf("_"));
			var oShape = window.external.parentWindow.document.getElementById(oShapeid);
			if (oShape.value ==2)
			{
				oShape.objects("RGConTxtCusParam").style.visibility = "Inherit";
				oShape.objects("RGConAlpCusParam").style.visibility = "Hidden";
				oShape.objects("RGTxtCusParam").style.visibility = "Hidden";
				oShape.objects("RGConTxtCusParam").focus;
			}
