				oShape.objects("RVTxtCusParam").style.visibility = "Hidden";
				oShape.objects("RVConTxtCusParam").focus;
			}
			if (oShape.value ==4)
			{
				oShape.objects("DIConTxtCusParam").style.visibility = "Inherit";
