	if( !window.external.IsAccessPermitted( window.external.parentWindow.document.activeElement )) this.disabled=true; return true;

				var strPointName,objPopupWindow,objHdxPopup;

				objHdxPopup = window.external.parentWindow.document.getElementById("HDXPopupBehavior");

				if (objHdxPopup!= null)

				{ 
					var oShapeid = window.external.parentWindow.document.activeElement.id.substring(0, window.external.parentWindow.document.activeElement.id.indexOf("_"));
					var oShape = window.external.parentWindow.document.getElementById(oShapeid);
					if (oShape.value ==2)
					{
						if (oShape.Objects("RGConalpTagName").value!=null)
						{
							strPointName = oShape.Objects("RGConalpTagName").value;
							objHdxPopup.CreatePopupWindow("syshsecteng_fp.htm?CurrentPoint="+strPointName, 0, 0, 1);			
						}
					}
					if (oShape.value ==3)
					{
						if (oShape.Objects("RVConalpTagName").value!=null)

						{
							strPointName = oShape.Objects("RVConalpTagName").value;
							objHdxPopup.CreatePopupWindow("syshsecteng_fp.htm?CurrentPoint="+strPointName, 0, 0, 1);
						}
					}
					if (oShape.value ==4)
					{
						if (oShape.Objects("DIConalpTagName").value!=null)

						{
							strPointName = oShape.Objects("DIConalpTagName").value;
							objHdxPopup.CreatePopupWindow ("syshsecteng_fp.htm?CurrentPoint="+strPointName, 0, 0, 1);
						}
					}
					

				}
			window.external.CloseShortcutMenu();

